package org.apache.parquet.filter2;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

public class IncrementallyUpdatedFilterPredicateGeneratorTests {

  private static final String PACKAGE_DECLARATION = "package org.apache.parquet.filter2.recordlevel;\n";

  private static String generate(Path outputFile) throws IOException {
    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(outputFile.toFile());
    generator.run();
    return Files.readString(outputFile);
  }

  private static long countOccurrences(String haystack, String needle) {
    int count = 0;
    int index = haystack.indexOf(needle);
    while (index >= 0) {
      count++;
      index = haystack.indexOf(needle, index + needle.length());
    }
    return count;
  }

  @Test
  void runGeneratesCompleteBuilderSource(@TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .startsWith(PACKAGE_DECLARATION)
        .contains("import java.util.Iterator;")
        .contains("import java.util.List;")
        .contains("import java.util.Set;")
        .contains("import org.apache.parquet.io.api.Binary;")
        .contains("import org.apache.parquet.schema.PrimitiveComparator;")
        .contains("public class IncrementallyUpdatedFilterPredicateBuilder "
            + "extends IncrementallyUpdatedFilterPredicateBuilderBase {")
        .contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves) {")
        .contains("super(leaves);")
        .contains("throw new IllegalArgumentException(\"Encountered unknown type \" + clazz);")
        .endsWith("}\n");

    // Every generated block must be closed; a truncated generation would leave unbalanced braces.
    assertThat(countOccurrences(source, "{")).isEqualTo(countOccurrences(source, "}"));
  }

  @ParameterizedTest
  @ValueSource(strings = {"Eq", "NotEq", "In", "NotIn", "Contains", "Lt", "LtEq", "Gt", "GtEq"})
  void generatedSourceDeclaresVisitorForEachPredicateOperator(String operator, @TempDir Path tempDir)
      throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("  @Override\n"
            + "  public <T extends Comparable<T>> IncrementallyUpdatedFilterPredicate visit("
            + operator + "<T> pred) {");
  }

  @ParameterizedTest
  @CsvSource({"Integer, int", "Long, long", "Boolean, boolean", "Float, float", "Double, double", "Binary, Binary"})
  void generatedSourceContainsEqualityHandlingForEachType(
      String className, String primitiveName, @TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("final " + primitiveName + " target = (" + className + ") (Object) pred.getValue();")
        .contains("final PrimitiveComparator<" + className + "> comparator = getComparator(columnPath);")
        .contains("setResult(comparator.compare(value, target) == 0 );");
  }

  @ParameterizedTest
  @CsvSource({"Integer, int", "Long, long", "Boolean, boolean", "Float, float", "Double, double", "Binary, Binary"})
  void generatedSourceContainsNotEqualityHandlingForEachType(
      String className, String primitiveName, @TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("final " + primitiveName + " target = (" + className + ") (Object) pred.getValue();")
        .contains("final PrimitiveComparator<" + className + "> comparator = getComparator(columnPath);")
        .contains("setResult(comparator.compare(value, target) != 0);");
  }

  @ParameterizedTest
  @CsvSource({"Integer, int", "Long, long", "Boolean, boolean", "Float, float", "Double, double", "Binary, Binary"})
  void generatedSourceContainsInAndNotInHandlingForEachType(
      String className, String primitiveName, @TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("final Set<" + className + "> target = (Set<" + className + ">) pred.getValues();")
        .contains("final boolean containsNull = target.contains(null);")
        .contains("for (" + className + " i : target) {")
        .contains(primitiveName + " targetValue = i;")
        .contains("if (i == null) { continue; }")
        .contains("setResult(containsNull);")
        .contains("setResult(!containsNull);");
  }

  @ParameterizedTest
  @ValueSource(strings = {"<", "<=", ">", ">="})
  void generatedSourceContainsInequalityHandlingForSupportedTypesAndRejectsBoolean(
      String operator, @TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    // Integer, Long, Float, Double and Binary each get an inequality branch for this operator.
    assertThat(countOccurrences(source, "setResult(comparator.compare(value, target) " + operator + " 0);"))
        .isEqualTo(5);
    // The rejection is emitted both by the regular visitor and by the Contains inspector visitor.
    assertThat(countOccurrences(
            source,
            "throw new IllegalArgumentException(\"Operator " + operator + " not supported for Boolean\");"))
        .isEqualTo(2);
  }

  @Test
  void generatedSourceContainsUserDefinedAndInvertedUserDefinedHandling(@TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("UserDefined<T, U> pred = notPred.getUserDefined();")
        .contains("setResult(udp.acceptsNullValue());")
        .contains("setResult(udp.keep((T) (Object) value));")
        .contains("setResult(!udp.acceptsNullValue());")
        .contains("setResult(!udp.keep((T) (Object) value));");
  }

  @Test
  void generatedSourceContainsContainsPredicateInfrastructure(@TempDir Path tempDir) throws IOException {
    String source = generate(tempDir.resolve("Builder.java"));

    assertThat(source)
        .contains("private abstract static class ContainsPredicate extends DelegatingValueInspector")
        .contains("private static class ContainsSinglePredicate extends ContainsPredicate")
        .contains("private static class ContainsAndPredicate extends ContainsPredicate")
        .contains("private static class ContainsOrPredicate extends ContainsPredicate")
        .contains("valueInspector = new ContainsInspectorVisitor().visit(pred);")
        .contains("return contains.filter(this, ContainsAndPredicate::new, "
            + "ContainsOrPredicate::new, ContainsPredicate::not);")
        .contains("return new ContainsSinglePredicate(valueInspector, false);")
        .contains(
            "throw new UnsupportedOperationException(\"Operators.And not supported for Contains predicate\");")
        .contains(
            "throw new UnsupportedOperationException(\"Operators.Or not supported for Contains predicate\");")
        .contains(
            "throw new UnsupportedOperationException(\"Operators.Not not supported for Contains predicate\");")
        .contains(
            "throw new UnsupportedOperationException(\"UserDefinedPredicate not supported for Contains predicate\");")
        .contains("throw new UnsupportedOperationException("
            + "\"LogicalNotUserDefined not supported for Contains predicate\");");
  }

  @Test
  void mainCreatesPackageDirectoriesAndWritesGeneratedBuilder(@TempDir Path tempDir) throws IOException {
    Path outputRoot = tempDir.resolve("generated-src");
    Path expectedBuilder = outputRoot.resolve(
        "org/apache/parquet/filter2/recordlevel/IncrementallyUpdatedFilterPredicateBuilder.java");

    assertThat(outputRoot).doesNotExist();

    IncrementallyUpdatedFilterPredicateGenerator.main(new String[] {outputRoot.toString()});

    assertThat(expectedBuilder).isRegularFile();
    assertThat(Files.readString(expectedBuilder)).isEqualTo(generate(tempDir.resolve("Direct.java")));
  }

  @Test
  void constructorFailsWhenOutputFileCannotBeCreated(@TempDir Path tempDir) throws IOException {
    Path regularFile = tempDir.resolve("not-a-directory");
    Files.writeString(regularFile, "contents");

    Path uncreatableFile = regularFile.resolve("Builder.java");

    assertThatThrownBy(() -> new IncrementallyUpdatedFilterPredicateGenerator(uncreatableFile.toFile()))
        .isInstanceOf(IOException.class);
  }

  @Test
  void runTruncatesAnExistingOutputFile(@TempDir Path tempDir) throws IOException {
    Path outputFile = tempDir.resolve("Builder.java");
    Files.writeString(outputFile, "stale content that must not survive generation");

    String source = generate(outputFile);

    assertThat(source)
        .startsWith(PACKAGE_DECLARATION)
        .doesNotContain("stale content that must not survive generation");
  }

  @Test
  void runClosesItsFileWriter(@TempDir Path tempDir) throws IOException {
    IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(
        tempDir.resolve("Builder.java").toFile());
    generator.run();

    // The first run flushes and closes its writer, so reusing the generator cannot silently append.
    assertThatThrownBy(generator::run).isInstanceOf(IOException.class);
  }
}
