import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class ParquetMetadataConverterTests {

  private static final String CREATED_BY = "parquet-mr version 1.12.0 (build test)";

  private final ParquetMetadataConverter converter = new ParquetMetadataConverter();

  // -------------------------------------------------------------------------
  // Constructors
  // -------------------------------------------------------------------------

  @Test
  void rejectsNonPositiveStatisticsTruncateLength() {
    assertThatThrownBy(() -> new ParquetMetadataConverter(0))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");

    assertThatThrownBy(() -> new ParquetMetadataConverter(-7))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");
  }

  @Test
  void acceptsPositiveStatisticsTruncateLength() {
    assertThatCode(() -> new ParquetMetadataConverter(1)).doesNotThrowAnyException();
    assertThatCode(ParquetMetadataConverter::new).doesNotThrowAnyException();
  }

  // -------------------------------------------------------------------------
  // Schema conversion
  // -------------------------------------------------------------------------

  @Test
  void toParquetSchemaConvertsPrimitiveGroupAndLogicalTypes() {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .id(1)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(stringType())
        .id(2)
        .named("name")
        .optional(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY)
        .length(16)
        .as(decimalType(2, 10))
        .named("amount")
        .optional(PrimitiveTypeName.INT64)
        .as(timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS))
        .named("ts")
        .optionalGroup()
        .as(listType())
        .addField(Types.repeatedGroup()
            .addField(Types.required(PrimitiveTypeName.INT32).named("element"))
            .named("list"))
        .named("tags")
        .named("root");

    List<SchemaElement> elements = converter.toParquetSchema(schema);

    assertThat(elements).hasSize(8);

    SchemaElement root = elements.get(0);
    assertThat(root.getName()).isEqualTo("root");
    assertThat(root.isSetType()).isFalse();
    assertThat(root.isSetRepetition_type()).isFalse();
    assertThat(root.getNum_children()).isEqualTo(5);

    SchemaElement id = elements.get(1);
    assertThat(id.getName()).isEqualTo("id");
    assertThat(id.getType()).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(id.getRepetition_type()).isEqualTo(FieldRepetitionType.REQUIRED);
    assertThat(id.getField_id()).isEqualTo(1);
    assertThat(id.isSetLogicalType()).isFalse();
    assertThat(id.isSetConverted_type()).isFalse();

    SchemaElement name = elements.get(2);
    assertThat(name.getName()).isEqualTo("name");
    assertThat(name.getType()).isEqualTo(org.apache.parquet.format.Type.BYTE_ARRAY);
    assertThat(name.getRepetition_type()).isEqualTo(FieldRepetitionType.OPTIONAL);
    assertThat(name.getField_id()).isEqualTo(2);
    assertThat(name.getConverted_type()).isEqualTo(ConvertedType.UTF8);
    assertThat(name.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.STRING);

    SchemaElement amount = elements.get(3);
    assertThat(amount.getType()).isEqualTo(org.apache.parquet.format.Type.FIXED_LEN_BYTE_ARRAY);
    assertThat(amount.getType_length()).isEqualTo(16);
    assertThat(amount.getPrecision()).isEqualTo(10);
    assertThat(amount.getScale()).isEqualTo(2);
    assertThat(amount.getConverted_type()).isEqualTo(ConvertedType.DECIMAL);
    assertThat(amount.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.DECIMAL);
    assertThat(amount.getLogicalType().getDECIMAL().getPrecision()).isEqualTo(10);
    assertThat(amount.getLogicalType().getDECIMAL().getScale()).isEqualTo(2);

    SchemaElement ts = elements.get(4);
    assertThat(ts.getType()).isEqualTo(org.apache.parquet.format.Type.INT64);
    assertThat(ts.getConverted_type()).isEqualTo(ConvertedType.TIMESTAMP_MICROS);
    assertThat(ts.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.TIMESTAMP);
    assertThat(ts.getLogicalType().getTIMESTAMP().isIsAdjustedToUTC()).isTrue();
    assertThat(ts.getLogicalType().getTIMESTAMP().getUnit().getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.MICROS);

    SchemaElement tags = elements.get(5);
    assertThat(tags.isSetType()).isFalse();
    assertThat(tags.getRepetition_type()).isEqualTo(FieldRepetitionType.OPTIONAL);
    assertThat(tags.getConverted_type()).isEqualTo(ConvertedType.LIST);
    assertThat(tags.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.LIST);
    assertThat(tags.getNum_children()).isEqualTo(1);

    SchemaElement list = elements.get(6);
    assertThat(list.isSetType()).isFalse();
    assertThat(list.getRepetition_type()).isEqualTo(FieldRepetitionType.REPEATED);
    assertThat(list.getNum_children()).isEqualTo(1);

    SchemaElement element = elements.get(7);
    assertThat(element.getName()).isEqualTo("element");
    assertThat(element.getType()).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(element.getRepetition_type()).isEqualTo(FieldRepetitionType.REQUIRED);
  }

  @Test
  void toParquetMetadataWritesSchemaRowsKeyValuesAndColumnOrders() {
    List<BlockMetaData> blocks = List.of(newBlock(4, 10, 100), newBlock(104, 20, 100), newBlock(204, 30, 100));
    Map<String, String> keyValues = new LinkedHashMap<>();
    keyValues.put("k1", "v1");
    keyValues.put("k2", "v2");
    ParquetMetadata metadata = new ParquetMetadata(new FileMetaData(testSchema(), keyValues, CREATED_BY), blocks);

    org.apache.parquet.format.FileMetaData fileMetaData = converter.toParquetMetadata(1, metadata);

    assertThat(fileMetaData.getVersion()).isEqualTo(1);
    assertThat(fileMetaData.getNum_rows()).isEqualTo(60);
    assertThat(fileMetaData.getCreated_by()).isEqualTo(CREATED_BY);
    assertThat(fileMetaData.getSchema()).hasSize(3);
    assertThat(fileMetaData.getKey_value_metadata())
        .extracting(KeyValue::getKey, KeyValue::getValue)
        .containsExactlyInAnyOrder(tuple("k1", "v1"), tuple("k2", "v2"));
    assertThat(fileMetaData.getColumn_orders()).hasSize(2);
    assertThat(fileMetaData.getColumn_orders().get(0).isSetTYPE_ORDER()).isTrue();
    assertThat(fileMetaData.getColumn_orders().get(1).isSetTYPE_ORDER()).isTrue();

    assertThat(fileMetaData.getRow_groups()).hasSize(3);
    RowGroup first = fileMetaData.getRow_groups().get(0);
    assertThat(first.getNum_rows()).isEqualTo(10);
    assertThat(first.getTotal_byte_size()).isEqualTo(100);
    assertThat(first.getFile_offset()).isEqualTo(4);
    assertThat(first.getTotal_compressed_size()).isEqualTo(100);
    assertThat(first.getOrdinal()).isEqualTo((short) 0);
    assertThat(first.getColumns()).hasSize(1);

    ColumnChunk columnChunk = first.getColumns().get(0);
    assertThat(columnChunk.getFile_path()).isEqualTo("part-0.parquet");
    ColumnMetaData columnMetaData = columnChunk.getMeta_data();
    assertThat(columnMetaData.getType()).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(columnMetaData.getPath_in_schema()).containsExactly("id");
    assertThat(columnMetaData.getCodec()).isEqualTo(CompressionCodec.UNCOMPRESSED);
    assertThat(columnMetaData.getEncodings()).containsExactly(org.apache.parquet.format.Encoding.PLAIN);
    assertThat(columnMetaData.getNum_values()).isEqualTo(10);
    assertThat(columnMetaData.getData_page_offset()).isEqualTo(4);
    assertThat(columnMetaData.isSetDictionary_page_offset()).isFalse();
    assertThat(columnMetaData.getTotal_compressed_size()).isEqualTo(100);
    assertThat(columnMetaData.getTotal_uncompressed_size()).isEqualTo(100);
    assertThat(columnMetaData.isSetStatistics()).isTrue();
    assertThat(BytesUtils.bytesToInt(columnMetaData.getStatistics().getMin_value()))
        .isEqualTo(1);
    assertThat(BytesUtils.bytesToInt(columnMetaData.getStatistics().getMax_value()))
        .isEqualTo(9);
  }

  @Test
  void toParquetMetadataWritesColumnOrdersForFloatingPointInt96AndUndefinedTypes() {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("i")
        .optional(PrimitiveTypeName.DOUBLE)
        .named("d")
        .optional(PrimitiveTypeName.INT96)
        .named("t")
        .optional(PrimitiveTypeName.INT32)
        .columnOrder(org.apache.parquet.schema.ColumnOrder.undefined())
        .named("u")
        .named("root");
    ParquetMetadata metadata =
        new ParquetMetadata(new FileMetaData(schema, Map.of(), CREATED_BY), List.of());

    org.apache.parquet.format.FileMetaData fileMetaData = converter.toParquetMetadata(1, metadata);

    List<ColumnOrder> orders = fileMetaData.getColumn_orders();
    assertThat(orders).hasSize(4);
    assertThat(orders.get(0).isSetTYPE_ORDER()).isTrue();
    assertThat(orders.get(1).isSetIEEE_754_TOTAL_ORDER()).isTrue();
    assertThat(orders.get(2).isSetINT96_TIMESTAMP_ORDER()).isTrue();
    assertThat(orders.get(3).isSetTYPE_ORDER()).isTrue();
  }

  @Test
  void toParquetMetadataRejectsInvalidBlockStartingPosition() {
