  @Test
  void fromParquetMetadataRoundTripsSchemaBlocksAndStatistics() throws IOException {
    List<BlockMetaData> blocks = List.of(newBlock(4, 10, 100), newBlock(104, 20, 100));
    ParquetMetadata metadata = new ParquetMetadata(
        new FileMetaData(testSchema(), Map.of("k", "v"), CREATED_BY), blocks);
    org.apache.parquet.format.FileMetaData fileMetaData = converter.toParquetMetadata(1, metadata);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData);

    assertThat(result.getFileMetaData().getCreatedBy()).isEqualTo(CREATED_BY);
    assertThat(result.getFileMetaData().getKeyValueMetaData()).containsEntry("k", "v");
    assertThat(result.getFileMetaData().getSchema()).isEqualTo(testSchema());
    assertThat(result.getBlocks()).hasSize(2);

    BlockMetaData first = result.getBlocks().get(0);
    assertThat(first.getRowCount()).isEqualTo(10);
    assertThat(first.getTotalByteSize()).isEqualTo(100);
    assertThat(first.getOrdinal()).isZero();
    assertThat(first.getPath()).isEqualTo("part-0.parquet");
    assertThat(first.getColumns()).hasSize(1);

    ColumnChunkMetaData column = first.getColumns().get(0);
    assertThat(column.getPath()).isEqualTo(ColumnPath.get("id"));
    assertThat(column.getPrimitiveType()).isEqualTo(
        Types.required(PrimitiveTypeName.INT32).id(1).named("id"));
    assertThat(column.getCodec()).isEqualTo(CompressionCodecName.UNCOMPRESSED);
    assertThat(column.getEncodings()).containsExactly(Encoding.PLAIN);
    assertThat(column.getValueCount()).isEqualTo(10);
    assertThat(column.getFirstDataPageOffset()).isEqualTo(4);
    assertThat(column.getTotalSize()).isEqualTo(100);
    assertThat(column.getTotalUncompressedSize()).isEqualTo(100);
    assertThat(column.getStatistics().getNumNulls()).isZero();
    assertThat(BytesUtils.bytesToInt(column.getStatistics().getMinBytes())).isEqualTo(1);
    assertThat(BytesUtils.bytesToInt(column.getStatistics().getMaxBytes())).isEqualTo(9);
    assertThat(column.getEncodingStats()).isNotNull();
    assertThat(column.getEncodingStats().getNumDataPagesEncodedAs(Encoding.PLAIN)).isEqualTo(1);

    BlockMetaData second = result.getBlocks().get(1);
    assertThat(second.getRowCount()).isEqualTo(20);
    assertThat(second.getOrdinal()).isEqualTo(1);
    assertThat(second.getColumns().get(0).getFirstDataPageOffset()).isEqualTo(104);
  }

  @Test
  void fromParquetMetadataAssignsRowIndexOffsetsFromMap() throws IOException {
    org.apache.parquet.format.FileMetaData fileMetaData = toFormatMetadata();
    Map<RowGroup, Long> rowIndexOffsets = new HashMap<>();
    long rowOffset = 0;
    for (RowGroup rowGroup : fileMetaData.getRow_groups()) {
      rowIndexOffsets.put(rowGroup, rowOffset);
      rowOffset += rowGroup.getNum_rows();
    }

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, rowIndexOffsets);

    assertThat(result.getBlocks()).hasSize(3);
    assertThat(result.getBlocks().get(0).getRowIndexOffset()).isZero();
    assertThat(result.getBlocks().get(1).getRowIndexOffset()).isEqualTo(10);
    assertThat(result.getBlocks().get(2).getRowIndexOffset()).isEqualTo(30);
  }

