  @Test
  void convertUnitMapsMicrosMillisAndNanos() {
    assertThat(ParquetMetadataConverter.convertUnit(LogicalTypeAnnotation.TimeUnit.MICROS)
            .getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.MICROS);
    assertThat(ParquetMetadataConverter.convertUnit(LogicalTypeAnnotation.TimeUnit.MILLIS)
            .getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.MILLIS);
    assertThat(ParquetMetadataConverter.convertUnit(LogicalTypeAnnotation.TimeUnit.NANOS)
            .getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.NANOS);
  }

  @Test
  void encodingMappingRoundTripsEveryEncoding() {
    for (Encoding encoding : Encoding.values()) {
      org.apache.parquet.format.Encoding formatEncoding = converter.getEncoding(encoding);
      assertThat(formatEncoding).isNotNull();
      assertThat(converter.getEncoding(formatEncoding)).isEqualTo(encoding);
    }
  }

  @Test
  void convertEncodingStatsFromFormatTracksDictionaryDataAndV2Pages() {
    List<PageEncodingStats> formatStats = List.of(
        new PageEncodingStats(PageType.DICTIONARY_PAGE, org.apache.parquet.format.Encoding.PLAIN, 2),
        new PageEncodingStats(
            PageType.DATA_PAGE, org.apache.parquet.format.Encoding.RLE_DICTIONARY, 3),
        new PageEncodingStats(
            PageType.DATA_PAGE_V2, org.apache.parquet.format.Encoding.DELTA_BINARY_PACKED, 4));

    EncodingStats stats = converter.convertEncodingStats(formatStats);

    assertThat(stats.getDictionaryEncodings()).containsExactly(Encoding.PLAIN);
    assertThat(stats.getNumDictionaryPagesEncodedAs(Encoding.PLAIN)).isEqualTo(2);
    assertThat(stats.getDataEncodings())
        .containsExactlyInAnyOrder(Encoding.RLE_DICTIONARY, Encoding.DELTA_BINARY_PACKED);
    assertThat(stats.getNumDataPagesEncodedAs(Encoding.RLE_DICTIONARY))
        .isEqualTo(3);
    assertThat(stats.getNumDataPagesEncodedAs(Encoding.DELTA_BINARY_PACKED))
        .isEqualTo(4);
    assertThat(stats.usesV2Pages()).isTrue();
  }

  @Test
  void convertEncodingStatsReturnsNullForNullInput() {
    assertThat(converter.convertEncodingStats((List<PageEncodingStats>) null)).isNull();
    assertThat(converter.convertEncodingStats((EncodingStats) null)).isNull();
  }

  @Test
  void convertEncodingStatsToFormatUsesDataPageV2WhenConfigured() {
    EncodingStats stats = new EncodingStats.Builder()
        .addDictEncoding(Encoding.PLAIN, 2)
        .addDataEncoding(Encoding.RLE_DICTIONARY, 3)
        .withV2Pages()
        .build();

    List<PageEncodingStats> formatStats = converter.convertEncodingStats(stats);

    assertThat(formatStats).hasSize(2);
    assertThat(formatStats.get(0).getPage_type()).isEqualTo(PageType.DICTIONARY_PAGE);
    assertThat(formatStats.get(0).getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.PLAIN);
    assertThat(formatStats.get(0).getCount()).isEqualTo(2);
    assertThat(formatStats.get(1).getPage_type()).isEqualTo(PageType.DATA_PAGE_V2);
    assertThat(formatStats.get(1).getEncoding())
        .isEqualTo(org.apache.parquet.format.Encoding.RLE_DICTIONARY);
    assertThat(formatStats.get(1).getCount()).isEqualTo(3);
  }

