  @Test
  void toParquetStatisticsIncludesMinMaxNullAndNanCounts() {
    IntStatistics stats = new IntStatistics();
    stats.setMinMax(1, 10);
    stats.setNumNulls(2);
    stats.incrementNanCount(3);

    org.apache.parquet.format.Statistics formatStats = ParquetMetadataConverter.toParquetStatistics(stats);

    assertThat(formatStats.getNull_count()).isEqualTo(2);
    assertThat(formatStats.getNan_count()).isEqualTo(3);
    assertThat(BytesUtils.bytesToInt(formatStats.getMin())).isEqualTo(1);
    assertThat(BytesUtils.bytesToInt(formatStats.getMax())).isEqualTo(10);
    assertThat(BytesUtils.bytesToInt(formatStats.getMin_value())).isEqualTo(1);
    assertThat(BytesUtils.bytesToInt(formatStats.getMax_value())).isEqualTo(10);
  }

  @Test
  void toParquetStatisticsOnlyWritesV2MinMaxForUnsignedTypes() {
    BinaryStatistics stats = new BinaryStatistics();
    stats.setMinMax(Binary.fromString("aaa"), Binary.fromString("zzz"));
    stats.setNumNulls(0);

    org.apache.parquet.format.Statistics formatStats = ParquetMetadataConverter.toParquetStatistics(stats);

    assertThat(formatStats.getNull_count()).isZero();
    assertThat(formatStats.isSetMin()).isFalse();
    assertThat(formatStats.isSetMax()).isFalse();
    assertThat(formatStats.getMin_value()).containsExactly("aaa".getBytes(StandardCharsets.UTF_8));
    assertThat(formatStats.getMax_value()).containsExactly("zzz".getBytes(StandardCharsets.UTF_8));
  }

  @Test
  void toParquetStatisticsLeavesEmptyStatisticsEmpty() {
    org.apache.parquet.format.Statistics formatStats =
        ParquetMetadataConverter.toParquetStatistics(new IntStatistics());

    assertThat(formatStats.isSetNull_count()).isFalse();
    assertThat(formatStats.isSetMin()).isFalse();
    assertThat(formatStats.isSetMax()).isFalse();
    assertThat(formatStats.isSetMin_value()).isFalse();
    assertThat(formatStats.isSetMax_value()).isFalse();
  }

  @Test
  void toParquetStatisticsDropsOversizedBinaryStatistics() {
    byte[] oversized = new byte[(int) ParquetMetadataConverter.MAX_STATS_SIZE];
    BinaryStatistics stats = new BinaryStatistics();
    stats.setMinMaxFromBytes(oversized, oversized);
    stats.setNumNulls(0);

    org.apache.parquet.format.Statistics formatStats =
        ParquetMetadataConverter.toParquetStatistics(stats, Integer.MAX_VALUE);

    assertThat(formatStats.isSetNull_count()).isFalse();
    assertThat(formatStats.isSetMin_value()).isFalse();
    assertThat(formatStats.isSetMax_value()).isFalse();
  }

  @Test
  void fromParquetStatisticsReadsV2MinMaxAndNullCount() {
    org.apache.parquet.format.Statistics formatStats = new org.apache.parquet.format.Statistics();
    formatStats.setMin_value(BytesUtils.intToBytes(5));
    formatStats.setMax_value(BytesUtils.intToBytes(15));
    formatStats.setNull_count(4);
    formatStats.setNan_count(2);

    org.apache.parquet.column.statistics.Statistics stats = converter.fromParquetStatistics(
        CREATED_BY, formatStats, Types.optional(PrimitiveTypeName.INT32).named("i"));

    assertThat(stats.getNumNulls()).isEqualTo(4);
    assertThat(stats.getNanCount()).isEqualTo(2);
    assertThat(BytesUtils.bytesToInt(stats.getMinBytes())).isEqualTo(5);
    assertThat(BytesUtils.bytesToInt(stats.getMaxBytes())).isEqualTo(15);
  }

  @Test
  void fromParquetStatisticsReadsLegacyMinMaxForSignedTypes() {
