  @Test
  void fromParquetStatisticsDropsLegacyMinMaxForUnsignedStringType() {
    org.apache.parquet.format.Statistics formatStats = new org.apache.parquet.format.Statistics();
    formatStats.setMin("aaa".getBytes(StandardCharsets.UTF_8));
    formatStats.setMax("zzz".getBytes(StandardCharsets.UTF_8));
