  @Test
  void fromParquetStatisticsAcceptsLegacyStringStatsWhenMinEqualsMax() {
    org.apache.parquet.format.Statistics formatStats = new org.apache.parquet.format.Statistics();
    byte[] value = "same".getBytes(StandardCharsets.UTF_8);
    formatStats.setMin(value);
    formatStats.setMax(value);

