        .isEqualTo(org.apache.parquet.format.Type.BYTE_ARRAY);
    assertThat(converter.getType(PrimitiveTypeName.INT64))
        .isEqualTo(org.apache.parquet.format.Type.INT64);
    assertThat(converter.getType(PrimitiveTypeName.INT32))
        .isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(converter.getType(PrimitiveTypeName.BOOLEAN))
        .isEqualTo(org.apache.parquet.format.Type.BOOLEAN);
