  @Test
  void repetitionMappingsRoundTrip() {
    for (Repetition repetition : Repetition.values()) {
      FieldRepetitionType formatRepetition = converter.toParquetRepetition(repetition);
      assertThat(formatRepetition.name()).isEqualTo(repetition.name());
      assertThat(converter.fromParquetRepetition(formatRepetition)).isEqualTo(repetition);
    }
  }

  @Test
  void convertToLogicalTypeMapsLogicalAnnotations() {
    assertThat(converter.convertToLogicalType(stringType()).getSetField())
        .isEqualTo(LogicalType._Fields.STRING);
    assertThat(converter.convertToLogicalType(enumType()).getSetField())
        .isEqualTo(LogicalType._Fields.ENUM);
    assertThat(converter.convertToLogicalType(jsonType()).getSetField())
        .isEqualTo(LogicalType._Fields.JSON);
    assertThat(converter.convertToLogicalType(bsonType()).getSetField())
        .isEqualTo(LogicalType._Fields.BSON);
    assertThat(converter.convertToLogicalType(dateType()).getSetField())
        .isEqualTo(LogicalType._Fields.DATE);
    assertThat(converter.convertToLogicalType(uuidType()).getSetField())
        .isEqualTo(LogicalType._Fields.UUID);
    assertThat(converter.convertToLogicalType(float16Type()).getSetField())
        .isEqualTo(LogicalType._Fields.FLOAT16);
    assertThat(converter.convertToLogicalType(intervalType()).getSetField())
        .isEqualTo(LogicalType._Fields.UNKNOWN);

    LogicalType decimal = converter.convertToLogicalType(decimalType(2, 10));
    assertThat(decimal.getSetField()).isEqualTo(LogicalType._Fields.DECIMAL);
    assertThat(decimal.getDECIMAL().getScale()).isEqualTo(2);
    assertThat(decimal.getDECIMAL().getPrecision()).isEqualTo(10);

    LogicalType time = converter.convertToLogicalType(
        timeType(false, LogicalTypeAnnotation.TimeUnit.NANOS));
    assertThat(time.getSetField()).isEqualTo(LogicalType._Fields.TIME);
    assertThat(time.getTIME().isIsAdjustedToUTC()).isFalse();
    assertThat(time.getTIME().getUnit().getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.NANOS);

    LogicalType timestamp = converter.convertToLogicalType(
        timestampType(true, LogicalTypeAnnotation.TimeUnit.MILLIS));
    assertThat(timestamp.getSetField()).isEqualTo(LogicalType._Fields.TIMESTAMP);
    assertThat(timestamp.getTIMESTAMP().isIsAdjustedToUTC()).isTrue();
    assertThat(timestamp.getTIMESTAMP().getUnit().getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.MILLIS);

    LogicalType integer = converter.convertToLogicalType(intType(16, false));
    assertThat(integer.getSetField()).isEqualTo(LogicalType._Fields.INTEGER);
    assertThat(integer.getINTEGER().getBitWidth()).isEqualTo((byte) 16);
    assertThat(integer.getINTEGER().isIsSigned()).isFalse();

    LogicalType variant = converter.convertToLogicalType(variantType((byte) 1));
    assertThat(variant.getSetField()).isEqualTo(LogicalType._Fields.VARIANT);
    assertThat(variant.getVARIANT().getSpecification_version()).isEqualTo((byte) 1);

    LogicalType geometry = converter.convertToLogicalType(geometryType("OGC:CRS84"));
    assertThat(geometry.getSetField()).isEqualTo(LogicalType._Fields.GEOMETRY);
    assertThat(geometry.getGEOMETRY().getCrs()).isEqualTo("OGC:CRS84");

    LogicalType geography = converter.convertToLogicalType(
        geographyType("OGC:CRS84", EdgeInterpolationAlgorithm.VINCENTY));
    assertThat(geography.getSetField()).isEqualTo(LogicalType._Fields.GEOGRAPHY);
    assertThat(geography.getGEOGRAPHY().getCrs()).isEqualTo("OGC:CRS84");
    assertThat(geography.getGEOGRAPHY().getAlgorithm())
        .isEqualTo(org.apache.parquet.format.EdgeInterpolationAlgorithm.VINCENTY);
  }

