  @Test
  void filterFileMetaDataByStartUsesRowGroupFileOffsetsWithoutColumnMetadata() {
    RowGroup first = rowGroupWithoutMetadata(4, 100, 10);
    RowGroup second = rowGroupWithoutMetadata(104, 100, 20);
    RowGroup third = rowGroupWithoutMetadata(204, 100, 30);
    org.apache.parquet.format.FileMetaData fileMetaData = new org.apache.parquet.format.FileMetaData();
    fileMetaData.setRow_groups(List.of(first, second, third));

    org.apache.parquet.format.FileMetaData filtered = ParquetMetadataConverter.filterFileMetaDataByStart(
        fileMetaData, new ParquetMetadataConverter.OffsetMetadataFilter(Set.of(4L, 104L)));

    assertThat(filtered.getRow_groups()).containsExactly(first, second);
  }

  @Test
  void filterFileMetaDataByStartRejectsCorruptSubsequentFileOffset() {
    RowGroup first = rowGroupWithoutMetadata(4, 100, 10);
    RowGroup corrupt = rowGroupWithoutMetadata(50, 100, 20);
    org.apache.parquet.format.FileMetaData fileMetaData = new org.apache.parquet.format.FileMetaData();
    fileMetaData.setRow_groups(List.of(first, corrupt));

    assertThatThrownBy(() -> ParquetMetadataConverter.filterFileMetaDataByStart(
            fileMetaData, new ParquetMetadataConverter.OffsetMetadataFilter(Set.of(50L))))
        .isInstanceOf(InvalidFileOffsetException.class)
        .hasMessageContaining("corrupted RowGroup.file_offset found");
  }

  @Test
  void filterFileMetaDataByMidpointRecoversFromCorruptFileOffset() {
    RowGroup corruptFirst = rowGroupWithoutMetadata(10, 100, 10);
    RowGroup corruptSecond = rowGroupWithoutMetadata(50, 100, 20);
    org.apache.parquet.format.FileMetaData fileMetaData = new org.apache.parquet.format.FileMetaData();
    fileMetaData.setRow_groups(List.of(corruptFirst, corruptSecond));

    org.apache.parquet.format.FileMetaData filtered =
        ParquetMetadataConverter.filterFileMetaDataByMidpoint(
            fileMetaData, new ParquetMetadataConverter.RangeMetadataFilter(0, 200));

    // First row group is normalized to offset 4 (midpoint 54) and the corrupt
    // second offset is replaced by 4 + 100 = 104 (midpoint 154).
    assertThat(filtered.getRow_groups()).containsExactly(corruptFirst, corruptSecond);
  }

