  @Test
  void buildColumnChunkMetaDataMapsFormatFields() {
    org.apache.parquet.format.Statistics statistics = new org.apache.parquet.format.Statistics();
    statistics.setMin_value(BytesUtils.intToBytes(2));
    statistics.setMax_value(BytesUtils.intToBytes(8));
    statistics.setNull_count(1);
    ColumnMetaData metaData = new ColumnMetaData(
        org.apache.parquet.format.Type.INT32,
        List.of(org.apache.parquet.format.Encoding.PLAIN),
        List.of("id"),
        CompressionCodec.SNAPPY,
        5,
        120,
        80,
        16);
    metaData.setStatistics(statistics);
    metaData.setEncoding_stats(List.of(
        new PageEncodingStats(PageType.DATA_PAGE, org.apache.parquet.format.Encoding.PLAIN, 1)));
    metaData.setSize_statistics(new org.apache.parquet.format.SizeStatistics()
        .setUnencoded_byte_array_data_bytes(32)
        .setRepetition_level_histogram(List.of(1L))
        .setDefinition_level_histogram(List.of(2L)));

    ColumnChunkMetaData column = converter.buildColumnChunkMetaData(
        metaData,
        ColumnPath.get("id"),
        Types.required(PrimitiveTypeName.INT32).named("id"),
        CREATED_BY);

    assertThat(column.getPath()).isEqualTo(ColumnPath.get("id"));
    assertThat(column.getType()).isEqualTo(PrimitiveTypeName.INT32);
    assertThat(column.getCodec()).isEqualTo(CompressionCodecName.SNAPPY);
    assertThat(column.getEncodings()).containsExactly(Encoding.PLAIN);
    assertThat(column.getValueCount()).isEqualTo(5);
    assertThat(column.getFirstDataPageOffset()).isEqualTo(16);
    assertThat(column.getTotalSize()).isEqualTo(80);
    assertThat(column.getTotalUncompressedSize()).isEqualTo(120);
    assertThat(BytesUtils.bytesToInt(column.getStatistics().getMinBytes())).isEqualTo(2);
    assertThat(BytesUtils.bytesToInt(column.getStatistics().getMaxBytes())).isEqualTo(8);
    assertThat(column.getStatistics().getNumNulls()).isEqualTo(1);
    assertThat(column.getEncodingStats().getNumDataPagesEncodedAs(Encoding.PLAIN))
        .isEqualTo(1);
    assertThat(column.getSizeStatistics()).isNotNull();
    assertThat(column.getSizeStatistics().getUnencodedByteArrayDataBytes())
        .contains(32L);
    assertThat(column.getSizeStatistics().getRepetitionLevelHistogram()).containsExactly(1L);
    assertThat(column.getSizeStatistics().getDefinitionLevelHistogram()).containsExactly(2L);
  }

