  // ---------------------------------------------------------------- column / offset index

  @Test
  void columnIndexRoundTripsThroughFormat() {
    PrimitiveType type = Types.optional(PrimitiveTypeName.INT32).named("x");
    ColumnIndex index = ColumnIndexBuilder.build(
        type,
        BoundaryOrder.ASCENDING,
        List.of(false, false),
        List.of(1L, 2L),
        List.of(ByteBuffer.wrap(BytesUtils.intToBytes(1)), ByteBuffer.wrap(BytesUtils.intToBytes(3))),
        List.of(ByteBuffer.wrap(BytesUtils.intToBytes(2)), ByteBuffer.wrap(BytesUtils.intToBytes(4))));

    org.apache.parquet.format.ColumnIndex format = ParquetMetadataConverter.toParquetColumnIndex(type, index);

    assertThat(format.getBoundary_order()).isEqualTo(org.apache.parquet.format.BoundaryOrder.ASCENDING);
    assertThat(format.getNull_pages()).containsExactly(false, false);
    assertThat(format.getNull_counts()).containsExactly(1L, 2L);
    assertThat(format.getMin_values()).containsExactly(
        ByteBuffer.wrap(BytesUtils.intToBytes(1)), ByteBuffer.wrap(BytesUtils.intToBytes(3)));
    assertThat(format.getMax_values()).containsExactly(
        ByteBuffer.wrap(BytesUtils.intToBytes(2)), ByteBuffer.wrap(BytesUtils.intToBytes(4)));

    ColumnIndex roundTrip = ParquetMetadataConverter.fromParquetColumnIndex(type, format);

    assertThat(roundTrip.getBoundaryOrder()).isEqualTo(BoundaryOrder.ASCENDING);
    assertThat(roundTrip.getNullPages()).containsExactly(false, false);
    assertThat(roundTrip.getNullCounts()).containsExactly(1L, 2L);
    assertThat(roundTrip.getMinValues()).containsExactly(
        ByteBuffer.wrap(BytesUtils.intToBytes(1)), ByteBuffer.wrap(BytesUtils.intToBytes(3)));
    assertThat(roundTrip.getMaxValues()).containsExactly(
        ByteBuffer.wrap(BytesUtils.intToBytes(2)), ByteBuffer.wrap(BytesUtils.intToBytes(4)));
  }

  @Test
  void columnIndexRoundTripsOptionalCountsAndHistograms() {
