    assertThat(format.getRepetition_level_histograms()).containsExactly(2L, 2L);
    assertThat(format.getDefinition_level_histograms()).containsExactly(3L, 3L);

    ColumnIndex roundTrip = ParquetMetadataConverter.fromParquetColumnIndex(type, format);

    assertThat(roundTrip.getNanCounts()).containsExactly(0L, 1L);
    assertThat(roundTrip.getRepetitionLevelHistogram()).containsExactly(2L, 2L);
    assertThat(roundTrip.getDefinitionLevelHistogram()).containsExactly(3L, 3L);
