  @Test
  void sizeStatisticsRoundTripsThroughFormat() {
    PrimitiveType type = Types.optional(PrimitiveTypeName.INT32).named("x");
    SizeStatistics stats = new SizeStatistics(type, 123L, List.of(1L, 2L), List.of(3L, 4L));

    org.apache.parquet.format.SizeStatistics format = ParquetMetadataConverter.toParquetSizeStatistics(stats);

    assertThat(format.getUnencoded_byte_array_data_bytes()).isEqualTo(123);
    assertThat(format.getRepetition_level_histogram()).containsExactly(1L, 2L);
    assertThat(format.getDefinition_level_histogram()).containsExactly(3L, 4L);

    SizeStatistics roundTrip = ParquetMetadataConverter.fromParquetSizeStatistics(format, type);
    assertThat(roundTrip.getType()).isEqualTo(type);
    assertThat(roundTrip.getUnencodedByteArrayDataBytes()).contains(123L);
    assertThat(roundTrip.getRepetitionLevelHistogram()).containsExactly(1L, 2L);
    assertThat(roundTrip.getDefinitionLevelHistogram()).containsExactly(3L, 4L);
  }

