  void sizeStatisticsConversionHandlesNull() {
    assertThat(ParquetMetadataConverter.toParquetSizeStatistics(null)).isNull();
    assertThat(ParquetMetadataConverter.fromParquetSizeStatistics(null, Types.optional(PrimitiveTypeName.INT32).named("x")))
        .isNull();
  }

  @Test
  void bloomFilterHeaderUsesFilterProperties() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(32);

    BloomFilterHeader header = ParquetMetadataConverter.toBloomFilterHeader(filter);

    assertThat(header.getNumBytes()).isEqualTo(filter.getBitsetSize());
    assertThat(header.getAlgorithm().getSetField()).isEqualTo(BloomFilterAlgorithm._Fields.BLOCK);
    assertThat(header.getHash().getSetField()).isEqualTo(BloomFilterHash._Fields.XXHASH);
    assertThat(header.getCompression().getSetField()).isEqualTo(BloomFilterCompression._Fields.UNCOMPRESSED);
  }

