  void edgeInterpolationAlgorithmMappingsRoundTrip() {
    for (org.apache.parquet.format.EdgeInterpolationAlgorithm thrift :
        org.apache.parquet.format.EdgeInterpolationAlgorithm.values()) {
      org.apache.parquet.column.schema.EdgeInterpolationAlgorithm parquet =
          ParquetMetadataConverter.toParquetEdgeInterpolationAlgorithm(thrift);
      assertThat(ParquetMetadataConverter.fromParquetEdgeInterpolationAlgorithm(parquet))
          .isEqualTo(thrift);
    }
    assertThat(ParquetMetadataConverter.fromParquetEdgeInterpolationAlgorithm(null)).isNull();
    assertThat(ParquetMetadataConverter.toParquetEdgeInterpolationAlgorithm(null)).isNull();
  }

