  private static MessageType testSchema() {
    return Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .id(1)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(stringType())
        .named("name")
        .named("test_schema");
  }

  private ParquetMetadata newParquetMetadata(Map<String, String> keyValues, long[] offsets, long[] rows, long[] sizes) {
    List<BlockMetaData> blocks = new ArrayList<>();
    for (int i = 0; i < offsets.length; i++) {
      blocks.add(newBlock(offsets[i], rows[i], sizes[i]));
    }
    return new ParquetMetadata(new FileMetaData(testSchema(), keyValues, CREATED_BY), blocks);
  }

  private org.apache.parquet.format.FileMetaData newFormatMetadata() {
    ParquetMetadata metadata =
        newParquetMetadata(Map.of("k", "v"), new long[] {4, 104}, new long[] {10, 20}, new long[] {100, 100});
    return converter.toParquetMetadata(1, metadata);
  }

  private static BlockMetaData newBlock(long dataPageOffset, long rowCount, long totalSize) {
    IntStatistics stats = new IntStatistics();
    stats.setMinMax(1, 9);
    stats.setNumNulls(0);
    ColumnChunkMetaData column = ColumnChunkMetaData.get(
        ColumnPath.get("id"),
        Types.required(PrimitiveTypeName.INT32).named("id"),
        CompressionCodecName.UNCOMPRESSED,
        new EncodingStats.Builder().addDataEncoding(Encoding.PLAIN, 1).build(),
        Set.of(Encoding.PLAIN),
        stats,
        dataPageOffset,
        0L,
        rowCount,
        totalSize,
        totalSize);
    BlockMetaData block = new BlockMetaData();
    block.setRowCount(rowCount);
    block.setTotalByteSize(totalSize);
    block.setPath("part-0.parquet");
    block.addColumn(column);
    return block;
  }

  private static ColumnChunkMetaData newColumn(long dataPageOffset, long dictionaryPageOffset) {
    return ColumnChunkMetaData.get(
        ColumnPath.get("id"),
        Types.required(PrimitiveTypeName.INT32).named("id"),
        CompressionCodecName.UNCOMPRESSED,
        null,
        Set.of(Encoding.PLAIN),
        new IntStatistics(),
        dataPageOffset,
        dictionaryPageOffset,
        10,
        100,
        100);
  }

  private org.apache.parquet.format.FileMetaData formatWithoutColumnMetadata(long... rowGroupOffsets) {
    List<RowGroup> rowGroups = new ArrayList<>();
    for (long offset : rowGroupOffsets) {
      RowGroup rowGroup = new RowGroup(List.of(new org.apache.parquet.format.ColumnChunk(0)), 100, 10);
      rowGroup.setFile_offset(offset);
      rowGroup.setTotal_compressed_size(100);
      rowGroups.add(rowGroup);
    }
    org.apache.parquet.format.FileMetaData format = new org.apache.parquet.format.FileMetaData();
    format.setRow_groups(rowGroups);
    return format;
  }

  private static byte[] serialize(org.apache.parquet.format.FileMetaData metadata) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    Util.writeFileMetaData(metadata, out);
    return out.toByteArray();
  }
