  @Test
  void offsetIndexRoundTripsUnencodedByteArrayDataBytes() {
    OffsetIndex index = OffsetIndexBuilder.getBuilder()
        .add(4L, 100, 0L, Optional.of(60L))
        .add(104L, 50, 10L, Optional.of(20L))
        .build();

    org.apache.parquet.format.OffsetIndex format = ParquetMetadataConverter.toParquetOffsetIndex(index);

    assertThat(format.getPage_locations()).hasSize(2);
    assertThat(format.getPage_locations().get(0)).isEqualTo(new PageLocation(4L, 100, 0L));
    assertThat(format.getPage_locations().get(1)).isEqualTo(new PageLocation(104L, 50, 10L));
    assertThat(format.isSetUnencoded_byte_array_data_bytes()).isTrue();
    assertThat(format.getUnencoded_byte_array_data_bytes()).containsExactly(60L, 20L);

    OffsetIndex roundTrip = ParquetMetadataConverter.fromParquetOffsetIndex(format);
    assertThat(roundTrip.getPageCount()).isEqualTo(2);
    assertThat(roundTrip.getOffset(0)).isEqualTo(4);
    assertThat(roundTrip.getCompressedPageSize(0)).isEqualTo(100);
    assertThat(roundTrip.getFirstRowIndex(0)).isZero();
    assertThat(roundTrip.getOffset(1)).isEqualTo(104);
    assertThat(roundTrip.getUnencodedByteArrayDataBytes(0)).contains(60L);
    assertThat(roundTrip.getUnencodedByteArrayDataBytes(1)).contains(20L);
  }

