    assertThat(format.isSetUnencoded_byte_array_data_bytes()).isFalse();
    OffsetIndex roundTrip = ParquetMetadataConverter.fromParquetOffsetIndex(format);
    assertThat(roundTrip.getUnencodedByteArrayDataBytes(0)).isEmpty();
    assertThat(roundTrip.getUnencodedByteArrayDataBytes(1)).isEmpty();
  }

