  @Test
  void buildColumnChunkMetaDataMapsFormatFields() {
    ColumnMetaData metaData = new ColumnMetaData(
        org.apache.parquet.format.Type.INT32,
        List.of(org.apache.parquet.format.Encoding.PLAIN),
        List.of("id"),
        CompressionCodec.UNCOMPRESSED,
        5,
        120,
        100,
        4);
    org.apache.parquet.format.Statistics formatStats = new org.apache.parquet.format.Statistics();
    formatStats.setMin_value(BytesUtils.intToBytes(2));
    formatStats.setMax_value(BytesUtils.intToBytes(8));
    formatStats.setNull_count(1);
    metaData.setStatistics(formatStats);
    metaData.setEncoding_stats(
        List.of(new PageEncodingStats(PageType.DATA_PAGE, org.apache.parquet.format.Encoding.PLAIN, 1)));
    metaData.setSize_statistics(new org.apache.parquet.format.SizeStatistics()
        .setUnencoded_byte_array_data_bytes(16)
        .setRepetition_level_histogram(List.of(1L))
        .setDefinition_level_histogram(List.of(2L)));

    PrimitiveType type = Types.required(PrimitiveTypeName.INT32).named("id");
    ColumnChunkMetaData column =
        converter.buildColumnChunkMetaData(metaData, ColumnPath.get("id"), type, CREATED_BY);

    assertThat(column.getPath()).isEqualTo(ColumnPath.get("id"));
    assertThat(column.getPrimitiveType()).isEqualTo(type);
    assertThat(column.getCodec()).isEqualTo(CompressionCodecName.UNCOMPRESSED);
    assertThat(column.getEncodings()).containsExactly(Encoding.PLAIN);
    assertThat(column.getValueCount()).isEqualTo(5);
    assertThat(column.getFirstDataPageOffset()).isEqualTo(4);
    assertThat(column.getTotalSize()).isEqualTo(100);
    assertThat(column.getTotalUncompressedSize()).isEqualTo(120);
    assertThat(column.getStatistics().getNumNulls()).isEqualTo(1);
    assertThat(BytesUtils.bytesToInt(column.getStatistics().getMinBytes())).isEqualTo(2);
    assertThat(column.getEncodingStats().getNumDataPagesEncodedAs(Encoding.PLAIN)).isEqualTo(1);
    assertThat(column.getSizeStatistics()).isNotNull();
    assertThat(column.getSizeStatistics().getUnencodedByteArrayDataBytes()).contains(16L);
  }

