  @Test
  void writeDataPageV1HeaderWritesExpectedHeader() throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    converter.writeDataPageV1Header(100, 80, 7, Encoding.RLE, Encoding.RLE, Encoding.PLAIN, out);

    PageHeader header = Util.readPageHeader(new ByteArrayInputStream(out.toByteArray()));
    assertThat(header.getType()).isEqualTo(PageType.DATA_PAGE);
    assertThat(header.getUncompressed_page_size()).isEqualTo(100);
    assertThat(header.getCompressed_page_size()).isEqualTo(80);
    assertThat(header.isSetCrc()).isFalse();
    DataPageHeader data = header.getData_page_header();
    assertThat(data.getNum_values()).isEqualTo(7);
